// Payload may be a plain string or {"value": "..."}.
let state = String(msg.payload).trim();
try {
    const parsed = JSON.parse(state);
    state = typeof parsed === 'object' && parsed !== null ? parsed.value : parsed;
} catch (e) { /* plain string */ }

if (state !== 'error') {
    return null;
}

// valetudo/<identifier>/StatusStateAttribute/status
const parts = msg.topic.split('/');
const vacuum = parts[parts.length - 3];
const base = (env.get('TUDOMESH_URL') || 'http://tudomesh:8080').replace(/\/$/, '');

msg.vacuum = vacuum;
msg.tudomesh = base;
msg.url = `${base}/vacuum/${encodeURIComponent(vacuum)}`;
return msg;

const info = msg.statusCode === 200 ? msg.payload : {};
const name = info.name || msg.vacuum;
const room = info.room ? info.room.name : 'an unknown room';

msg.alert = {
    title: `${name} is stuck`,
    message: `${name} reported an error in ${room}.`,
    vacuum: name,
    room: info.room ? info.room.name : null
};
msg.url = msg.tudomesh + (info.mapUrl || `/vacuum/${encodeURIComponent(msg.vacuum)}.png`) + '?crop=room';
return msg;

// msg.payload: PNG Buffer (or empty if tudomesh had no map)
// msg.alert:   { title, message, vacuum, room }
msg.image = msg.statusCode === 200 ? msg.payload : null;
msg.payload = msg.alert.message;
msg.topic = msg.alert.title;
return msg;
